BEGIN;
DO $qa$
DECLARE spec jsonb:='{"order_search_controls":{"screen":"orders","keys":["orderSearch","orderBranchFilter","orderStatusFilter","auditRefreshBtn"],"styleOnly":true},"order_manual_controls":{"screen":"orders","keys":["ff49ManualClose","ff49ManualDriver","ff49ManualReason","ff49ManualConfirm"],"styleOnly":true},"order_late_controls":{"screen":"orders","keys":["ff52LateClose","ff52LateItems","ff75LatePreview","ff52LateSave"],"styleOnly":true},"order_review_controls":{"screen":"orders","keys":["ffbCloseReview","ffbConfirmSave","ffbCancelReview"],"styleOnly":true},"driver_route_controls":{"screen":"driver","keys":["ff52RoutesClose","ff52RouteBranch","ff52RouteDriver","ff52RouteAreas","ff52RouteStart","ff52RouteEnd","ff52RouteActive","ff52RouteSave"],"styleOnly":true},"staff_link_controls":{"screen":"staff","keys":["addEmail","addName","addRole","addBranch","linkUserBtn"],"styleOnly":true},"dashboard_lifecycle_controls":{"screen":"dashboard","keys":["ff60-refresh","ff60-close","ff60-search","ff60-branch","ff60-state","ff60-open-old","ff60-fast","ff60-slow","ff60-save-policy"],"styleOnly":true},"dashboard_watch_controls":{"screen":"dashboard","keys":["ff4-refresh","ff4-export","ff4-close","ff4-search","ff4-branch","ff4-state","ff4-minutes"],"styleOnly":true},"dashboard_overdue_controls":{"screen":"dashboard","keys":["ff5-refresh","ff5-export","ff5-close","ff5-search","ff5-branch","ff5-age","ff5-sort"],"styleOnly":true},"driver_offer_controls":{"screen":"driver","keys":["offer_accept","offer_reject","offer_check_reject"],"styleOnly":true},"driver_progress_controls":{"screen":"driver","keys":["driver_on_way","driver_arrived","driver_delivered"],"styleOnly":true},"order_dynamic_actions":{"screen":"orders","keys":["order_customer_edit","order_auto","order_manual","order_change","order_reassign","order_transfer","order_cancel"],"styleOnly":true},"order_addition_controls":{"screen":"orders","keys":["additionItemsInput","addition_preview","addition_save","addition_close"],"styleOnly":true},"case_detail_controls":{"screen":"cases","keys":["ff41NextStatus","ff41Resolution","ff41CommentBody","case_transition","case_comment"],"styleOnly":true},"staff_edit_fields":{"screen":"staff","keys":["employee_name","employee_username","employee_email","employee_phone","employee_qualification","employee_address","employee_age","employee_marital","employee_experience","employee_password","employee_message"],"styleOnly":true}}'; g record; rows jsonb; patch jsonb; invalid jsonb;
BEGIN
 FOR g IN SELECT * FROM jsonb_each(spec) LOOP
 SELECT jsonb_agg(jsonb_build_object('key',k,'shape','pack','size','normal','align','center') ORDER BY ord) INTO rows FROM jsonb_array_elements_text(g.value->'keys') WITH ORDINALITY a(k,ord);
 patch:=jsonb_build_object(g.key,rows);
 IF NOT ff_private.a07_valid_elements(patch,g.value->>'screen') OR NOT ff_private.a07_valid_style(jsonb_build_object('elements',patch)) THEN RAISE EXCEPTION 'valid controls rejected %',g.key;END IF;
 IF ff_private.a07_valid_elements(patch,'finance') OR ff_private.a07_valid_elements(jsonb_build_object(g.key,jsonb_set(rows,'{0,key}','"unknown_unsafe"')),g.value->>'screen') THEN RAISE EXCEPTION 'scope or identity violation %',g.key;END IF;
 invalid:=jsonb_build_object(g.key,jsonb_set(rows,'{0,align}','"end"'));
 IF ff_private.a09_merge_elements(g.value->>'screen',patch,patch,invalid,ARRAY['buttons','layout','colors']) IS NOT NULL THEN RAISE EXCEPTION 'delegation bypass %',g.key;END IF;
 END LOOP;
END $qa$;
SELECT 'PASS STEP03 84 additional operational control keys' AS result;
ROLLBACK;
